auto pending = std::make_shared<std::atomic<int>>(recipients.size());
for (auto& r : recipients)
    asio::async_write(r.socket, asio::buffer(payload),
        [pending, done](error_code ec, size_t) {
            if (ec) record_failure(ec);
            if (--*pending == 0) done();     // last recipient -> fan-out complete
        });

asio::awaitable<void> fanOut(std::vector<Socket> recipients, std::string payload)
{
    for (auto& s : recipients)
        co_await asio::async_write(s, asio::buffer(payload),
                                   asio::as_tuple(asio::use_awaitable));
}   // every recipient has received its copy when the coroutine resumes
